/* t1 */ begin;
/* t2 */ begin;
/* t3 */ begin;

/* t1 */ delete from t where id = 1 and v = 1 and vv = 1;
/* t2 */ insert into t values(1, 2, 3, 4); -- block
/* t3 */ update t set id = 10, v = 20, vv = 30, vvv = 40 where v = 2 and vv = 3; -- will not block, 0 rows affected

